// Test the evalRule function logic directly
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', \`return (\${expr});\`)(ctx.ctx, req); // dynamic eval
}

// Test 1: amount > 100 with amount=150
let req = { body: { rule: 'ctx.amount > 100', context: { amount: 150 } } };
console.log('Test 1 - ctx.amount > 100 with amount=150:', evalRule(req)); // should be true

// Test 2: amount > 100 with amount=50
req = { body: { rule: 'ctx.amount > 100', context: { amount: 50 } } };
console.log('Test 2 - ctx.amount > 100 with amount=50:', evalRule(req)); // should be false

// Test 3: ctx.user.role === \"admin\"
req = { body: { rule: 'ctx.user.role === \"admin\"', context: { user: { role: 'admin' } } } };
console.log('Test 3 - ctx.user.role === admin:', evalRule(req)); // should be true

// Test 4: Using req (the full request object)
req = { body: { rule: 'req.method === \"POST\"', context: {} } };
console.log('Test 4 - req.method === POST:', evalRule(req)); // should be true

console.log('All tests passed!');
"

